        class FakeCursor:
            def __init__(self):
                self.sql_by_call = []
                self.params = []

            def execute(self, sql, params):
                self.sql_by_call.append(str(sql))
                self.params.append(params)

            def fetchone(self):
                rows = self.fetchall()
                return rows[0] if rows else None

