        cursor = FakeCursor()
        rows = _fetch_active_tracking_rows(cursor, args, n4_event_rows=[inactive_event])

        self.assertEqual(rows[0]["state_key"], state_key)
        self.assertEqual(cursor.params[1], ("20260703", [state_key]))

