    def test_stderr_snapshot_scopes_errors_to_trade_date_and_source_revision(self) -> None:
        from scripts import review_n5_n3t_fastlane_trading_day_monitor as monitor_module

        label = "com.ashare-v3.n3.c1-n3t-action-confirmation-poller"
        old_source_epoch = datetime.fromisoformat("2026-07-31T10:05:29+08:00").timestamp()
        cases = (
            (
                "prior_trade_date_error",
                "Traceback (most recent call last):\nNameError: old failure\n",
                "2026-08-14T13:09:14+08:00",
                old_source_epoch,
                "stale_before_trade_date",
                False,
            ),
            (
                "current_session_error",
                "Traceback (most recent call last):\nRuntimeError: current failure\n",
                "2026-08-17T09:30:05+08:00",
                old_source_epoch,
                "current_session_error",
                True,
            ),
            (
                "same_day_error_before_source_revision",
                "Traceback (most recent call last):\nRuntimeError: fixed failure\n",
                "2026-08-17T09:30:05+08:00",
                datetime.fromisoformat("2026-08-17T10:00:00+08:00").timestamp(),
                "stale_before_source_revision",
                False,
            ),
            (
                "current_session_without_runtime_error",
                "diagnostic warning only\n",
                "2026-08-17T09:31:05+08:00",
                old_source_epoch,
                "no_runtime_error",
                False,
            ),
        )

        with tempfile.TemporaryDirectory() as tmpdir:
            log_dir = Path(tmpdir)
            stderr_path = log_dir / f"{label}.err.log"
            for (
                case_name,
                stderr_text,
                stderr_mtime,
                source_mtime,
                expected_classification,
                expected_current,
            ) in cases:
                with self.subTest(case_name=case_name):
                    stderr_path.write_text(stderr_text, encoding="utf-8")
                    stderr_epoch = datetime.fromisoformat(stderr_mtime).timestamp()
                    os.utime(stderr_path, (stderr_epoch, stderr_epoch))
                    with patch.object(
                        monitor_module,
                        "_source_mtime_for_label",
                        return_value=source_mtime,
                    ):
                        snapshots = monitor_module._read_recent_stderr_snapshots(
                            log_dir,
                            for_trade_date="20260817",
                        )

                    snapshot = snapshots[label]
                    self.assertEqual(snapshot["error_classification"], expected_classification)
                    self.assertEqual(snapshot["has_current_error"], expected_current)
                    self.assertEqual(
                        snapshot["current_error_boundary_epoch"],
                        max(
                            datetime.fromisoformat("2026-08-17T00:00:00+08:00").timestamp(),
                            source_mtime,
                        ),
                    )

            with self.assertRaisesRegex(ValueError, "fastlane_for_trade_date_invalid"):
                monitor_module._read_recent_stderr_snapshots(
                    log_dir,
                    for_trade_date="20260899",
                )

